    fn lowering_retention_removes_messages_at_once() {
        let mut queue = standard();
        let mut ids = Ids::new();
        queue.send(0, &send("kept?"), &mut ids).unwrap();
        queue.set_attributes(100, Attributes { retention_seconds: 60, ..Attributes::default() });
        assert_eq!(queue.len(), 0);
    }
}
