        create(&mut broker, "dead");
        exec(&mut broker, r#"{"Command": "CreateQueue", "QueueName": "src", "Attributes": {"DeadLetterQueue": "dead", "MaxReceiveCount": 2}}"#).unwrap();
        exec(&mut broker, r#"{"Command": "DeleteQueue", "QueueName": "dead"}"#).unwrap();
        let attributes = exec(&mut broker, r#"{"Command": "GetQueueAttributes", "QueueName": "src"}"#).unwrap();
        assert!(!attributes["Attributes"].as_object().unwrap().contains_key("DeadLetterQueue"));
    }

    #[test]
    fn a_received_message_is_hidden_until_its_visibility_timeout_ends() {
        let mut broker = Broker::new();
        create(&mut broker, "q");
        send(&mut broker, "q", "hello");
        let first = receive(&mut broker, "q");
        assert_eq!(first.len(), 1);
        assert_eq!(
            first[0],
            json!({
                "MessageId": "m-1",
                "ReceiptHandle": "r-1",
                "Body": "hello",
                "ReceiveCount": 1,
                "SentAt": 0,
