        send(&mut broker, "q", "x");
        receive(&mut broker, "q");
        let change = r#"{"Command": "ChangeMessageVisibility", "QueueName": "q", "ReceiptHandle": "r-1", "VisibilityTimeout": 0}"#;
        exec(&mut broker, change).unwrap();
